        html: `<p>Відмова комісії оскаржується в адміністративному порядку до комісії центрального рівня та в адміністративному суді. І тут є аргумент, який у цій категорії справ працює найкраще.</p>
<p>Судова практика виходить із того, що рішення про зупинення реєстрації має містити <strong>конкретний і чіткий критерій</strong> оцінки ступеня ризиків, достатній для такого зупинення. Загальне формулювання в квитанції про те, що подані платником копії документів «складені із порушенням законодавства та/або не є достатніми для прийняття комісією рішення про реєстрацію податкової накладної», суди визнають <strong>неприпустимим</strong>: воно не дозволяє платнику зрозуміти, чого саме від нього хочуть, і фактично позбавляє можливості виправити ситуацію.</p>
<p>Що з цього випливає для підготовки позову:</p>
<ol>
<li><b>Зберігайте квитанції та рішення в оригінальному вигляді.</b> Саме їх текст є предметом оцінки.</li>
<li><b>Фіксуйте факт подання документів</b> — квитанції про прийняття, дати, перелік. Відмова, ухвалена без урахування поданого, — окрема підстава.</li>
<li><b>Формулюйте вимоги точно:</b> визнати протиправним і скасувати рішення комісії та зобов’язати зареєструвати накладну в Єдиному реєстрі із зазначенням дати її фактичного подання. Остання деталь важлива — вона визначає період, у якому покупець отримає кредит.</li>
</ol>
<p>Строки звернення до адміністративного суду обмежені, і досудове оскарження їх скорочує, тому судову перспективу варто оцінювати одночасно зі скаргою, а не після неї. Логіку оскарження податкових рішень ми розбираємо в матеріалі про <a href="/blog/oskarzhennya-ppr/">оскарження ППР</a>.</p>`,
