<p>Окремо: ФОП не може бути платником єдиного податку, якщо має <strong>податковий борг</strong> на день подання заяви про застосування спрощеної системи — за винятками, визначеними ПКУ. Про механіку боргу — у матеріалі про <a href="/blog/podatkovyj-borg-aresht-rahunkiv/">податковий борг та арешт рахунків</a>.</p>
