        h2: "Строк подання заяви: 10 календарних днів",
        html: `<p>Для добровільної відмови від спрощеної системи заява подається до контролюючого органу <strong>не пізніше ніж за 10 календарних днів до початку нового календарного кварталу або року</strong> (пп. 298.2.1 ПКУ).</p>
<p>Перехід відбувається <strong>з першого числа місяця, наступного за податковим (звітним) кварталом, у якому подано заяву</strong>.</p>
<p>На практиці це означає такий календар:</p>
<table>
<thead><tr><th>Коли потрібен перехід</th><th>Гранична дата заяви</th></tr></thead>
<tbody>
<tr><td>з 1 січня</td><td>не пізніше 21 грудня</td></tr>
<tr><td>з 1 квітня</td><td>не пізніше 21 березня</td></tr>
<tr><td>з 1 липня</td><td>не пізніше 21 червня</td></tr>
<tr><td>з 1 жовтня</td><td>не пізніше 21 вересня</td></tr>
</tbody>
</table>
<p>Пропущений строк означає, що перехід відкладається на наступний квартал — а разом із ним відкладаються й усі плани, які на нього спиралися: укладення договорів із компаніями на загальній системі, реєстрація платником ПДВ, участь у тендерах.</p>
<p>У частині джерел зустрічається строк «15 днів». Орієнтуватися варто на <strong>10 календарних днів</strong> за підпунктом 298.2.1 ПКУ — і все одно подавати раніше граничної дати, бо виправити помилку в заяві в останній день уже неможливо.</p>`,
