<p>Якщо виникає <strong>обов’язкова реєстрація</strong> за пунктом 181.1 ПКУ — за обсягом операцій, що перевищує встановлений поріг, — реєстраційна заява за формою № 1-ПДВ подається <strong>не пізніше 10 числа першого календарного місяця</strong>, у якому здійснено перехід на сплату інших податків і зборів.</p>
