        h2: "Три фільтри: коли операція стає контрольованою",
        html: `<p>Операція визнається контрольованою, лише якщо виконуються умови за <strong>всіма трьома</strong> групами критеріїв одночасно. Це головне, що варто перевірити перед тим, як занурюватися в методи.</p>
<ol>
<li><b>Суб’єктний критерій.</b> Операція з нерезидентом, який є: пов’язаною особою; резидентом держави з переліку низькоподаткових юрисдикцій, затвердженого Кабінетом Міністрів; особою з організаційно-правової форми з окремого переліку КМУ; комісіонером у операціях з товарами. Окремо — операції між нерезидентом і його постійним представництвом в Україні.</li>
<li><b>Характер операції.</b> Операція має впливати на об’єкт оподаткування податком на прибуток — тобто бути господарською операцією, що формує дохід або витрати.</li>
<li><b>Вартісні показники.</b> Пороги за обсягом, розібрані нижче.</li>
</ol>
<p>Про пов’язаність варто сказати окремо, бо саме тут найбільше хибних уявлень. Пов’язаність визначається не лише формальною часткою у статутному капіталі. Вона може встановлюватися через вплив на рішення, через кредитні відносини, а в оновлених підходах — і через <strong>економічну залежність без формального юридичного зв’язку</strong>, коли значна частка доходів або вартості продукції пов’язана з одним нерезидентом. Тому відповідь «ми не пов’язані, у нас немає спільних власників» не є остаточною.</p>`,
