        h2: "Звітність і документація",
        html: `<p>Обов’язків три, і вони різні за природою.</p>
<ol>
<li><b>Звіт про контрольовані операції.</b> Подається до <strong>1 жовтня</strong> року, що настає за звітним. Форма звіту затверджується наказом Мінфіну й періодично змінюється — перевіряйте чинну форму перед поданням. Передбачені нові та уточнюючі звіти: новий — до закінчення граничного строку подання за той самий період, уточнюючий — після його закінчення.</li>
<li><b>Документація з трансфертного ціноутворення.</b> Не подається автоматично — складається та подається <strong>на запит</strong> контролюючого органу. Її потрібно мати готовою, бо строк на подання після запиту короткий, а скласти якісну документацію за цей час неможливо.</li>
<li><b>Звітність міжнародних груп компаній.</b> Повідомлення про участь у МГК, глобальна документація (мастер-файл) і звіт у розрізі країн. Звіт у розрізі країн подається, якщо сукупний консолідований дохід групи за фінансовий рік, що передує звітному, дорівнює або перевищує встановлений поріг. Звіт містить дані по кожній юрисдикції та кожному учаснику групи — зокрема суму нерозподіленого прибутку, чисельність працівників і балансову вартість матеріальних активів.</li>
</ol>
<p>Штрафи за неподання звіту, документації та повідомлень встановлені в кратності до прожиткового мінімуму для працездатних осіб, тому їх гривневий розмір щороку змінюється; конкретні суми варто дивитися в чинній редакції ПКУ на дату порушення. Принципово інше: штраф за неподання документації не звільняє від обов’язку її подати, і несплата штрафу не закриває питання.</p>`,
