        h2: "Що робити власнику активів зараз",
        html: `<p>Послідовність, яку ми застосовуємо в роботі з такими ситуаціями.</p>
<ol>
<li><b>Інвентаризувати активи й джерела.</b> Скласти перелік: що є, коли набуто, за які кошти, які документи підтверджують джерело. Нерідко виявляється, що підтвердження є — просто розкидане.</li>
<li><b>Перевірити строки давності.</b> Частина епізодів уже за їх межами, і щодо них питання закрите. Це перше, що знімає тривогу й зменшує обсяг роботи.</li>
<li><b>Оцінити, що видно органу.</b> Дані CRS, реєстри нерухомості й транспорту, дані банків — важливо не те, що було, а те, що простежується.</li>
<li><b>Привести в порядок поточний режим.</b> Якщо є іноземні доходи або КІК, обов’язки виконуються з поточного періоду: нові порушення щороку погіршують позицію.</li>
<li><b>Підготувати документальну позицію щодо джерел</b> — заздалегідь, а не в момент запиту банку. Документ, зібраний під тиском, має іншу вагу.</li>
<li><b>Відстежувати законодавчі ініціативи.</b> Якщо новий механізм легалізації буде запроваджений, строк участі в ньому, як показав досвід 2021–2023 років, буде обмеженим.</li>
</ol>
<p>Прямо скажемо, чого ми не робимо: не обіцяємо легалізувати активи там, де механізму для цього немає. Коректна робота в цій ситуації — оцінити реальний ризик за кожним епізодом, закрити те, що закривається строками давності, і вибудувати документальну позицію щодо решти.</p>
<p>Таку оцінку ми проводимо в межах практики <a href="/practices/tax-law/">податкового права</a>, а спори з органом — у межах <a href="/practices/litigation/">судових спорів</a>. Більше матеріалів — у розділі <a href="/blog/podatkove-pravo/">податкове право</a>.</p>`,
