        id: "s2",
        h2: "Підстави: що саме доводити",
        html: `<p>Підстави для двох механізмів різні, і це визначає, який із них взагалі доступний.</p>
<p><b>Для розстрочення</b> платник подає достатні докази існування обставин, <strong>перелік яких визначається Кабінетом Міністрів України</strong>, що свідчать про загрозу виникнення або накопичення податкового боргу, а також економічне обґрунтування, яке свідчить про можливість погашення боргу в запропоновані строки.</p>
<p>Дві частини, і друга важить не менше за першу. Заява без економічного обґрунтування — без розрахунку, з якого видно, звідки візьмуться кошти за графіком, — не має сенсу: орган не має чим мотивувати позитивне рішення.</p>
<p><b>Для відстрочення</b> потрібні докази <strong>дії обставин непереборної сили</strong>. Це вужча й суворіша підстава, і підтверджувати її потрібно документально, а не описово.</p>
<p>Практичний порядок підготовки:</p>
<ol>
<li>з’ясувати, яка обставина з переліку КМУ відповідає вашій ситуації — <strong>перелік закритий</strong>, і «складне фінансове становище» загалом до нього не входить;</li>
<li>зібрати документи, що підтверджують саме цю обставину;</li>
<li>підготувати фінансовий розрахунок із джерелами погашення за графіком;</li>
<li>перевірити, чи немає підстав оспорити саме зобов’язання — це може бути вигіднішим.</li>
</ol>`,
