        id: "s3",
        h2: "Ціна механізму: проценти",
        html: `<p>Перенесення строку сплати не безкоштовне. Розстрочення й відстрочення здійснюються <strong>під проценти, розмір яких становить 120 % річних облікової ставки Національного банку України</strong> на день ухвалення рішення.</p>
<p>Це та цифра, яку потрібно порахувати до подання заяви. Два орієнтири для порівняння:</p>
<ul>
<li><b>штраф за прострочення</b> — 5 % або 10 % погашеної суми боргу залежно від тривалості, плюс пеня за кожен день; розміри ми розібрали в матеріалі про <a href="/blog/shtrafy-dps/">штрафи ДПС</a>;</li>
<li><b>банківський кредит</b> — якщо він доступний, порівняння за ставкою буває не на користь розстрочення.</li>
</ul>
<p>Тому розрахунок простий: якщо кошти з’являться за кілька тижнів, дешевше прострочити в межах 30 днів зі штрафом 5 %, ніж оформлювати розстрочення під проценти на рік. Якщо йдеться про місяці — картина змінюється, бо прострочення понад 30 днів дає 10 % плюс пеню плюс загрозу <a href="/blog/podatkovyj-borg-aresht-rahunkiv/">арешту та стягнення</a>.</p>
<p>Головна перевага розстрочення не в ставці, а в тому, що воно <strong>знімає загрозу примусового стягнення</strong>: сплата відбувається законно за графіком, а не з простроченням.</p>`,
