        h2: "Обов’язкові реквізити: коли можна не відповідати",
        html: `<p>Це найцінніша частина матеріалу, і саме її майже ніколи не перевіряють.</p>
<p>Пункт 73.3 ПКУ встановлює <strong>обов’язкові реквізити</strong>, які має містити законний запит. Якщо запит їх не містить, <strong>платник податків звільняється від обов’язку надавати відповідь</strong>.</p>
<p>Що перевіряти в отриманому запиті:</p>
<ol>
<li><b>Підстави для надіслання запиту</b> — конкретна норма ПКУ, за якою орган звертається. Не «з метою здійснення податкового контролю», а посилання на конкретний підпункт.</li>
<li><b>Інформацію, яка це підтверджує</b> — фактичні обставини, з яких випливає підстава. Орган має пояснити, що саме спричинило запит.</li>
<li><b>Перелік інформації та документів</b>, які запитуються, — конкретний, а не «усі документи щодо операцій».</li>
<li><b>Підпис уповноваженої посадової особи</b> та належне оформлення.</li>
</ol>
<p>Практично це означає, що перед підготовкою відповіді робиться <strong>аудит самого запиту</strong>. Типові дефекти: відсутність посилання на конкретну підставу, відсутність обставин, що її підтверджують, запит документів, не пов’язаних із зазначеною підставою.</p>
<p>Важливе застереження про тактику. Виявлений дефект не означає, що правильна дія — мовчати. Мовчання орган трактує як ненадання відповіді з відповідними наслідками, і доводити дефект доведеться вже в спорі про правомірність перевірки. Робоча тактика інша: <strong>надіслати мотивовану відповідь</strong>, у якій зазначити, яких саме реквізитів бракує, і на цій підставі повідомити про відсутність обов’язку надавати запитані документи. Це і фіксує позицію, і не створює формального ненадання відповіді.</p>`,
