<p>Акт про неможливість проведення зустрічної звірки складається, коли звірку провести не вдалося: суб’єкта не знайдено за адресою, документи не надано, посадові особи відсутні. Такий акт <strong>контролюючі органи використовують як доказ нереальності операцій</strong> — і не лише щодо того, з ким звірку не вдалося провести, а й щодо його контрагентів.</p>
